mapper.select:
select pro.P_Name as pName, con.Con_name as conName, c1.C_Name as qpContractorName, c2.C_Name as qpSupervisorName, mn.* from Me_Quality_Price mn left join Pre_Project pro on pro.P_Id = mn.P_Id left join Con_Contract con on con.Con_Id=mn.Con_Id left join Sys_Company c1 on c1.C_Id=mn.Qp_Contractor_Id left join Sys_Company c2 on c2.C_Id=mn.Qp_Supervisor_Id ${params.authSql}
and mn.Te_Id = #{params.teId}
and mn.P_Id=#{params.pId}
and mn.Qp_State=#{params.qpState}
and likePname(#{params.pName},pro.P_Id)=true
and INSTR(pro.P_Name,#{params.pName})
and INSTR(con.Con_name,#{params.conName})
and INSTR(mn.Qp_Create_Uname,#{params.qpCreateUname})
and INSTR(mn.Qp_First_Party_Rname,#{params.qpFirstPartyRname})
and INSTR(mn.Qp_Initiator_Name,#{params.qpInitiatorName})
and INSTR(mn.Qp_Title,#{params.qpTitle})
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Qp_Create_Time desc
